import { getServerSession } from "next-auth/next"
import { redirect } from "next/navigation"
import { authOptions, getOrganizerUserId } from "@/lib/auth"
import { profileService } from "@/services/profile.service"
import { assessmentService } from "@/services/assessment.service"
import AssessmentSystemClient from "./client-page"
import { Button } from "@/components/ui/button"
import { Suspense } from "react"
import Link from "next/link"

type SearchParams = Promise<{ [key: string]: string | string[] | undefined }>

export default async function AssessmentSystemPage(props: {
  searchParams: SearchParams
}) {
  const searchParams = await props.searchParams
  const session: any = await getServerSession(authOptions)
  if (!session) redirect("/auth/login")

  let events
  let assessmentData
  let event
  let eventId
  let levels: { id: string; name: string }[] = []
  let activeLevelId
  let fetchError = false

  try {
    // 1. Fetch Events for current Organizer
    events = await profileService.getEventsByUserId(
      session.accessToken,
      getOrganizerUserId(session)
    )

    if (events && events.length > 0) {
      event = events[0]
      eventId = event.id
      levels =
        event.event_levels?.map((l: any) => ({
          id: l.id,
          name: l.name,
        })) || []

      if (levels.length > 0) {
        // 2. Determine active level
        activeLevelId = (searchParams.level as string) || levels[0].id

        // 3. Fetch Assessment Data for the active level
        assessmentData = await assessmentService.getUnifiedAssessment(
          eventId,
          activeLevelId,
          session.accessToken
        )
      }
    }
  } catch (error) {
    console.error("Error in AssessmentSystemPage:", error)
    fetchError = true
  }

  if (fetchError) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <div className="mb-4 h-12 w-12 text-red-500">❌</div>
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Terjadi Kesalahan
        </h2>
        <p className="mt-2 text-slate-500">
          Gagal memuat data sistem penilaian.
        </p>
        <Link href="/organizer/dashboard/assessment-system">
          <Button variant="outline" className="mt-4 rounded-full">
            Coba Lagi
          </Button>
        </Link>
      </div>
    )
  }

  if (!events || events.length === 0) {
    redirect("/auth/register/eo/data-form")
  }


  if (levels.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <div className="mb-4 h-12 w-12 text-amber-500">⚠️</div>
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Jenjang Belum Ditentukan
        </h2>
        <p className="mt-2 text-slate-500">
          Silahkan tambahkan jenjang tingkat (SD/SMP/SMA) di menu My Event
          terlebih dahulu.
        </p>
      </div>
    )
  }

  return (
    <div className="flex flex-1 flex-col">
      <div className="mx-auto flex w-full max-w-7xl flex-col gap-6 p-4 md:gap-8 md:p-6 lg:p-8">
        {/* HEADER */}
        <h1 className="font-montserrat text-2xl font-bold text-slate-900 md:text-3xl">
          Sistem Penilaian
        </h1>

        <Suspense fallback={<div>Loading...</div>}>
          <AssessmentSystemClient
            eventId={eventId}
            levels={levels}
            activeLevelId={activeLevelId as string}
            initialData={assessmentData}
          />
        </Suspense>
      </div>
    </div>
  )
}

import { getServerSession } from "next-auth/next"
import { authOptions, getOrganizerUserId } from "@/lib/auth"
import { judgeService } from "@/services/judge.service"
import { profileService } from "@/services/profile.service"
import JudgeManagement from "@/components/organizer/judge-management"
import { AlertCircle } from "lucide-react"
import { Button } from "@/components/ui/button"

export default async function OrganizerJuryPage() {
  const session: any = await getServerSession(authOptions)

  if (!session?.accessToken || !session?.user?.id) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-red-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Sesi Berakhir
        </h2>
        <p className="mt-2 text-slate-600">
          Silakan login kembali untuk mengakses halaman ini.
        </p>
      </div>
    )
  }

  let eventId
  let judges
  let hasEvent = true

  try {
    // 1. Resolve EventID for this Organizer
    const events = await profileService.getEventsByUserId(
      session.accessToken,
      getOrganizerUserId(session)
    )

    if (!events || events.length === 0) {
      hasEvent = false
    } else {
      eventId = events[0].id // 1 Organizer = 1 Event rule
      // 2. Fetch Judges for this Event
      judges = await judgeService.getAllJudges(session.accessToken, eventId)
    }
  } catch (error) {
    console.error("Gagal memuat data juri:", error)
  }

  if (!hasEvent) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-amber-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Event Tidak Ditemukan
        </h2>
        // eslint-disable-next-line no-console
        <p className="mt-2 text-slate-600">
          Anda belum memiliki event yang terdaftar. Silakan buat event
          terlebih dahulu.
        </p>
      </div>
    )
  }

  if (!eventId || !judges) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-red-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Gagal Memuat Data
        </h2>
        <p className="mt-2 text-slate-600">
          Terjadi kesalahan saat mengambil data juri dari server.
        </p>
        <Button
          variant="outline"
          className="mt-4 rounded-full"
        >
          Muat Ulang
        </Button>
      </div>
    )
  }

  return <JudgeManagement eventId={eventId} initialJudges={judges} />
}

import React from "react"
import { AlertCircle } from "lucide-react"
import { getServerSession } from "next-auth/next"
import { authOptions, getOrganizerUserId } from "@/lib/auth"
import { profileService } from "@/services/profile.service"
import { rankingService } from "@/services/ranking.service"
import { rekapService } from "@/services/rekap.service"
import ScoreRecapClient from "./score-recap-client"

export default async function ScoreRecapPage() {
  const session: any = await getServerSession(authOptions)

  if (!session?.accessToken) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-red-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Akses Ditolak
        </h2>
        <p className="mt-2 text-neutral-500">Silakan login kembali.</p>
      </div>
    )
  }

  // 1. Get Event Data
  const events = await profileService.getEventsByUserId(
    session.accessToken,
    getOrganizerUserId(session)
  )
  const event = events.length > 0 ? events[0] : null

  if (!event) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-yellow-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Belum Ada Event
        </h2>
        <p className="mt-2 text-neutral-500">
          Anda belum memiliki event aktif.
        </p>
      </div>
    )
  }

  // 2. Fetch Initial Data for Score Recap
  const levels = (event.event_levels || []).map((l: any) => ({
    id: l.id,
    name: l.name,
  }))

  if (levels.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-yellow-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Belum Ada Jenjang
        </h2>
        <p className="mt-2 text-neutral-500">
          Silakan tambahkan jenjang lomba di menu My Event terlebih dahulu.
        </p>
      </div>
    )
  }

  let awards
  let initialScoreboardRes
  try {
    const res = await Promise.all([
      rankingService.getAwards(event.id, session.accessToken),
      rekapService.getScoreboard(levels[0].id, session.accessToken),
    ])
    awards = res[0]
    initialScoreboardRes = res[1]
  } catch (error) {
    console.error("Error fetching score recap data:", error)
  }

  if (!awards || !initialScoreboardRes) {
    return (

      <div className="flex flex-1 flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="mb-4 h-12 w-12 text-red-500" />
        <h2 className="font-montserrat text-xl font-bold text-slate-900">
          Terjadi Kesalahan
        </h2>
        <p className="mt-2 text-neutral-500">
          Gagal memuat data rekap nilai. Silakan coba lagi nanti.
        </p>
      </div>
    )
  }

  return (
    <ScoreRecapClient
      eventId={event.id}
      levels={levels}
      initialAwards={awards}
      initialScoreboard={initialScoreboardRes.items}
    />
  )
}

