function formatRupiah(amount: string | number) {
  if (
    amount === undefined ||
    amount === null ||
    amount === "" ||
    amount === "0"
  )
    return "-"
  const numericAmount = typeof amount === "string" ? parseInt(amount) : amount
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
  }).format(numericAmount || 0)
}

